import hashlib,json,os,re,statistics,subprocess,time
from pathlib import Path
out=Path('tests/out/intinf/rebase/final');perf=out/'performance';deadline=time.monotonic()+28800
while 'PASS normalized boundary repeats' not in (out/'dispatch-repeat.log').read_text():
 if time.monotonic()>deadline:raise SystemExit('normalized sweep did not finish')
 time.sleep(10)
os.sched_setaffinity(0,{min(os.sched_getaffinity(0))})
root=Path.cwd();load=lambda p:json.loads(Path(p).read_text());sha=lambda p:hashlib.sha256(Path(p).read_bytes()).hexdigest()
directory=(perf/'design-boundary').resolve();directory.mkdir();variant=(perf/'design/gmp').resolve()
reference=load(perf/'dispatch-repeat/report.json');design=load(perf/'design/report.json')
assert sha(variant/'lib/basis/intinf.sml')==design['modes']['gmp']['experimental_intinf_sha256']
primitive=[l.split()[0] for l in Path('runtime/prims.def').read_text().splitlines() if l.strip() and not l.startswith('#')].index('intinf_gmp_available')
query=re.compile(r'\bPRIM(?:PUSH)?\s+'+str(primitive)+r'\b')
env={k:v for k,v in os.environ.items() if not k.startswith('RUNEVM_') and k!='RUNE_GC_STRESS'}
report={'description':'Boundary controls using the previously verified constant-GMP Basis, same normalized library paths and source. These retain packed values, limits and import/export; selection also changes code layout.', 'driver_sha256':sha(__file__), 'samples':100,'warmup_pairs':2,'affinity':sorted(os.sched_getaffinity(0)),'vm_sha256':sha('bin/runevm'),'design_report_sha256':sha(perf/'design/report.json'),'dispatch_report_sha256':sha(perf/'dispatch-repeat/report.json'),'workloads':{}}
seq=0
def run(cmd,cwd=root):
 global seq
 seq+=1;cmd=list(map(str,cmd));prefix=directory/f'{seq:04d}'
 p=subprocess.run(cmd,cwd=cwd,env=env,capture_output=True,text=True,timeout=180)
 prefix.with_suffix('.command.json').write_text(json.dumps({'argv':cmd,'cwd':str(cwd)})+'\n');prefix.with_suffix('.stdout').write_text(p.stdout);prefix.with_suffix('.stderr').write_text(p.stderr)
 assert p.returncode==0,(cmd,p.stderr)
 return p.stdout,p.stderr
for name in ['add-128-128','mul-31-33']:
 w=reference['workloads'][name];source=(perf/'dispatch-repeat'/(name+'.sml')).resolve();normal=source.with_suffix('.rbc');specialized=directory/(name+'.rbc')
 run([root/'bin/rune','--lib','lib','-o',specialized,source],variant)
 text,_=run([root/'bin/runevm','--disasm',specialized]);assert not query.search(text)
 values={'normal':[],'specialized':[]};counts={}
 for i in range(102):
  for side in (['normal','specialized'] if i%2 else ['specialized','normal']):
   text,_=run([root/'bin/runevm','--intinf=gmp',normal if side=='normal' else specialized])
   timing,answer=text.split('\n',1);assert answer==w['expected'] and timing.startswith('TIMING ')
   if i>=2:values[side].append(float(timing[7:]))
 for side,path in [('normal',normal),('specialized',specialized)]:
  text,counts[side]=run([root/'bin/runevm','--intinf=gmp','--count',path]);assert text.split('\n',1)[1]==w['expected']
 ratios=[n/s for n,s in zip(values['normal'],values['specialized'])]
 report['workloads'][name]={'runs':values,'ratios':ratios,'median_ratio':statistics.median(ratios),'counts':counts,'source_sha256':sha(source),'bytecode_sha256':{'normal':sha(normal),'specialized':sha(specialized)}}
 (directory/'report.json').write_text(json.dumps(report,indent=2)+'\n');print(name,statistics.median(ratios),flush=True)
print('PASS boundary specialization controls',flush=True)
